fun lines(name: String)=File("input",name).readLines()
fun reals(w: List<String>,first: Int)=w.drop(first).map {
    it.toDouble()
}.toDoubleArray()
fun example(w: List<String>)=Example(w[0],Kernels.Point(w[1].toDouble(),w[2].toDouble()),w[3].toInt())
fun binary(name: String)=lines(name).drop(1).map {
    example(it.split(','))
}
fun read(): Data {
    val train=binary("train.csv");
    val test=binary("test.csv");
    val s=Settings()
    for(line in lines("params.txt")) {
        val w=line.split(' ');
        when(w[0]) {
            "C_GRID"->s.coefficients=reals(w,1)
            "KERNEL"-> {
                val kind=w[2];
                val degree=if(kind=="poly")w[3].toInt() else 0;
                val gamma=if(kind=="poly")w[4].toDouble() else if(kind=="rbf")w[3].toDouble() else 0.0;
                val offset=if(kind=="poly")w[5].toDouble() else 0.0;
                s.kernels.add(Kernels.Kernel(w[1],kind,degree,gamma,offset))
            }
            "TOLERANCE"->s.tolerance=w[1].toDouble()
            "EPS"->s.eps=w[1].toDouble()
            "MAX_PASSES"->s.maximum=w[1].toInt()
            "FOLDS"->s.folds=w[1].toInt()
        }
    }
    return Data(train,test,multiTrain,multiTest,s)
}
fun points(examples: List<Example>)=examples.map {
    it.point
}
fun labels(examples: List<Example>)=examples.map {
    it.label
}.toIntArray()
data class Point(val x: Double,val y: Double)
data class Kernel(val name: String,val kind: String,val degree: Int,val gamma: Double,val offset: Double) {
    fun value(a: Point,b: Point): Double {
        if(kind=="linear")return a.x*b.x+a.y*b.y
        if(kind=="poly") {
            val s=gamma*(a.x*b.x+a.y*b.y)+offset;
            var value=1.0;
            repeat(degree) {
                value*=s
            };
            return value
        }
        val e1=a.x-b.x;
        val e2=a.y-b.y;
        return exp(-gamma*(e1*e1+e2*e2))
    }
    fun matrix(points: List<Point>)=Array(points.size) {
        i->DoubleArray(points.size) {
            j->value(points[i],points[j])
        }
    }
}
fun submatrix(matrix: Array<DoubleArray>,indices: List<Int>)=Array(indices.size) {
    i->DoubleArray(indices.size) {
        j->matrix[indices[i]][indices[j]]
    }
}
fun sign(value: Double)=if(value>0)1 else -1
fun folds(size: Int,count: Int)=(0 until count).map {
    k->Fold((0 until size).filter {
        it%count!=k
    },(0 until size).filter {
        it%count==k
    })
